var __vite_injected_original_dirname = "/app/applet/src/lib";
function sanitizeForPdf(text) {
  if (!text) return "";
  return text.replace(/[\u201C\u201D\u201E\u201F\u00AB\u00BB]/g, '"').replace(/[\u2018\u2019\u201A\u201B]/g, "'").replace(/[\u2014\u2015]/g, " - ").replace(/[\u2012\u2013]/g, "-").replace(/[\u2026]/g, "...").replace(/[\u2022\u25E6\u25AA\u25AB]/g, "* ").replace(/\u00A0/g, " ").replace(/\r/g, "").replace(/[^\x00-\xFF]/g, (char) => {
    const norm = char.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return /^[\x20-\x7E\xA1-\xFF]$/.test(norm) ? norm : " ";
  }).replace(/[^\x20-\x7E\xA1-\xFF\n]/g, " ");
}
function wrapLine(text, maxWidth, font, fontSize) {
  const safeText = sanitizeForPdf(text).trim();
  if (!safeText) return [""];
  const words = safeText.split(/\s+/);
  const lines = [];
  let current = "";
  for (const word of words) {
    const test = current ? `${current} ${word}` : word;
    const width = font.widthOfTextAtSize(test, fontSize);
    if (width <= maxWidth) {
      current = test;
    } else {
      if (current) lines.push(current);
      current = word;
    }
  }
  if (current) lines.push(current);
  return lines;
}
