    const book = editorialBooks.find((b) => b.id === id) || catalog.books.find((b) => b.id === id);
    const title = book ? `${book.title} \u2014 Leitura Online | Wotho` : "Leitor Digital \u2014 Wotho";
    const desc = book?.description || "Leia a obra diretamente no navegador na plataforma Wotho.";
